mob is periods with row_number cross joined against itself. Use this mob calculation in Snowflake as reference:
CREATE OR REPLACE PROCEDURE SANDBOX_DS.SEGMENTACION.GENERAR_TABLA_MOB("DB_NAME" VARCHAR, "SCHEMA_NAME" VARCHAR, "TABLE_NAME" VARCHAR, "TIME_COLUMN" VARCHAR, "ID_COLUMNS" ARRAY)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS '
DECLARE
    fullY_qualified_table_name STRING;
    fully_qualified_basic_table_name STRING;
    mob_table STRING;
    id_list_str STRING;
    query_tabla_mob STRING;
BEGIN
    fullY_qualified_table_name := DB_NAME || ''.'' || SCHEMA_NAME || ''.'' || TABLE_NAME;
    fully_qualified_basic_table_name := DB_NAME || ''.'' || SCHEMA_NAME || ''.'' || TABLE_NAME || ''_BASE_TABLE'';
    mob_table := fullY_qualified_table_name || ''_TABLA_MOB'';

    query_tabla_mob := ''CREATE OR REPLACE TEMPORARY TABLE '' || mob_table || '' AS \\n'' ||
    ''WITH PERIODOS_UNICOS AS (\\n'' ||
        ''\\tSELECT DISTINCT '' || TIME_COLUMN || ''\\n'' ||
        ''\\tFROM '' || fullY_qualified_table_name || ''\\n'' ||
        ''\\tORDER BY '' || TIME_COLUMN || ''\\n'' ||
    ''),\\n'' ||
    ''PERIODOS_ORDENADOS AS (\\n'' ||
        ''\\tSELECT '' || TIME_COLUMN || '',\\n'' ||
        ''\\tROW_NUMBER() OVER(ORDER BY '' || TIME_COLUMN || '') AS MOB\\n'' ||
        ''\\tFROM PERIODOS_UNICOS\\n'' ||
    '')\\n'' ||
    ''SELECT\\n'' ||
        ''\\tA.'' || TIME_COLUMN || '' AS '' || TIME_COLUMN || ''_ANALYSIS,\\n'' ||
        ''\\tB.'' || TIME_COLUMN || '' AS '' || TIME_COLUMN || ''_RELATIVE,\\n'' ||
        ''\\tB.MOB - A.MOB AS MOB\\n'' ||
    ''FROM PERIODOS_ORDENADOS A\\n'' ||
    ''LEFT JOIN PERIODOS_ORDENADOS B\\n'' ||
    ''ON 1 = 1'';

    EXECUTE IMMEDIATE query_tabla_mob;
    RETURN query_tabla_mob;
END;
';

CALL SANDBOX_DS.SEGMENTACION.GENERAR_TABLA_MOB(
    'SANDBOX_DS',                     -- DB_NAME
    'SEGMENTACION',                   -- SCHEMA_NAME
    'SILVER_VENTA_NETA_CORP',         -- TABLE_NAME
    'PERIODO',                        -- TIME_COLUMN
    ARRAY_CONSTRUCT('ID_PAIS', 'ID_CLIENTE_ORIGEN')  -- ID_COLUMNS
);
